guardrail.bad:
try {
  await call();
} catch (error) {
  console.error(error.message); // 'error' is unknown — will throw at runtime
}

guardrail.good:
try {
  await call();
} catch (error: unknown) {
  if (error instanceof AppError) {
    logger.warn(error.message, { code: error.code });
    return res.status(error.statusCode).json({ error: error.message });
  }
  throw new AppError("Unexpected failure", "INTERNAL", 500, { cause: error });
}

guardrail.bad:
async function handler() {
  sendAnalytics(); // unhandled promise — silently drops errors
}

guardrail.good:
async function handler() {
  void sendAnalytics(); // explicit: intentionally not awaited
  // or
  await sendAnalytics();
}

guardrail.bad:
var count = 0;
try { riskyOp(); } catch (e) {}  // error swallowed
throw "something went wrong";    // primitive, no stack trace

guardrail.good:
let count = 0;
try { riskyOp(); } catch (e: unknown) { logger.error("riskyOp failed", { cause: e }); }
throw new AppError("something went wrong", "OP_FAILED");

const Status = {
  Active: "active",
  Inactive: "inactive",
} as const;
type Status = (typeof Status)[keyof typeof Status];

guardrail.bad:
// Sequential — slow when order does not matter
const users = await fetchUsers();
const posts = await fetchPosts();

guardrail.good:
async function fetchWithTimeout(url: string, ms: number): Promise<Response> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), ms);
  try {
    return await fetch(url, { signal: controller.signal });
  } finally {
    clearTimeout(timeout);
  }
}

guardrail.bad:
async function getUser(id: string) {
  return fetchUser(id).then(user => {
    const profile = await fetchProfile(user.profileId); // syntax error and confusing
    return profile;
  });
}

guardrail.good:
async function getUser(id: string) {
  const user = await fetchUser(id);
  return fetchProfile(user.profileId);
}

pattern.example:
class AppError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly statusCode: number = 500,
    options?: ErrorOptions
  ) {
    super(message, options);
    this.name = "AppError";
  }
}

class NotFoundError extends AppError {
  constructor(resource: string, id: string) {
    super(`${resource} with id ${id} not found`, "NOT_FOUND", 404);
    this.name = "NotFoundError";
  }
}

type Result<T, E = AppError> =
  | { ok: true; value: T }
  | { ok: false; error: E };

function parseAge(input: string): Result<number> {
  const age = Number(input);
  if (Number.isNaN(age) || age < 0 || age > 150) {
    return { ok: false, error: new AppError("Invalid age", "VALIDATION") };
  }
  return { ok: true, value: age };
}

// Caller must check before accessing value
const result = parseAge(input);
if (!result.ok) {
  return res.status(400).json({ error: result.error.message });
}
console.log(result.value); // type-safe: number

import { z } from "zod";

const CreateUserSchema = z.object({
  email: z.string().email(),
  name: z.string().min(1).max(100),
  age: z.number().int().min(0).max(150),
  role: z.enum(["admin", "user", "viewer"]),
});

type CreateUserInput = z.infer<typeof CreateUserSchema>;

// At API boundary — throws ZodError on failure
function handleCreateUser(rawBody: unknown): CreateUserInput {
  return CreateUserSchema.parse(rawBody);
}

import { z } from "zod";

const EnvSchema = z.object({
  DATABASE_URL: z.string().url(),
  PORT: z.coerce.number().int().min(1024).max(65535),
  NODE_ENV: z.enum(["development", "production", "test"]),
  JWT_SECRET: z.string().min(32),
});

export const env = EnvSchema.parse(process.env);

async function fetchWithTimeout(url: string, ms: number): Promise<Response> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), ms);
  try {
    return await fetch(url, { signal: controller.signal });
  } finally {
    clearTimeout(timeout);
  }
}

error-handling.pattern:
try {
  await externalService.call();
} catch (error: unknown) {
  if (error instanceof AppError) {
    logger.warn(error.message, { code: error.code });
    return res.status(error.statusCode).json({ error: error.message });
  }
  // Unknown error: wrap and re-throw with cause
  throw new AppError("Unexpected failure", "INTERNAL", 500, { cause: error });
}

const results = await Promise.allSettled([
  fetchUserProfile(userId),
  fetchUserPosts(userId),
  fetchUserSettings(userId),
]);

for (const result of results) {
  if (result.status === "rejected") {
    logger.warn("Partial fetch failure", { reason: result.reason });
  }
}

testing.pattern:
import { describe, it, expect } from "vitest";
import { validateEmail } from "./validate";

describe("validateEmail", () => {
  const cases = [
    { input: "user@example.com", expected: true,  desc: "valid email" },
    { input: "no-at-sign",       expected: false, desc: "missing @ symbol" },
    { input: "",                 expected: false, desc: "empty string" },
    { input: "a@b.c",           expected: true,  desc: "minimal valid email" },
  ] as const;

  it.each(cases)("returns $expected for $desc", ({ input, expected }) => {
    expect(validateEmail(input)).toBe(expected);
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { UserService } from "./user.service";
import type { UserRepository } from "./user.repository";

describe("UserService", () => {
  let service: UserService;
  let repo: UserRepository;

  beforeEach(() => {
    repo = {
      findById: vi.fn(),
      save: vi.fn(),
    } as unknown as UserRepository;
    service = new UserService(repo);
  });

  it("should throw NotFoundError when user does not exist", async () => {
    vi.mocked(repo.findById).mockResolvedValue(null);

    await expect(service.getUser("abc")).rejects.toThrow("not found");
    expect(repo.findById).toHaveBeenCalledWith("abc");
  });
});

